import pytest
from cart_module import Cart

@pytest.mark.parametrize("item_id, quantity", [
    ("item1", 0),
    ("item2", 0),
    ("item3", 0)
])
def test_set_quantity_to_zero_removes_item(cart, item_id, quantity):
    cart.set_quantity(item_id, quantity)
    assert item_id not in cart.items, f"Item {item_id} should have been removed from the cart"
